import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"14、【大有】 乾下離上","description":"周易集註 - 14、【大有】 乾下離上","frontmatter":{"title":"14、【大有】 乾下離上","description":"周易集註 - 14、【大有】 乾下離上"},"headers":[],"relativePath":"classics/jizhu/018.md","filePath":"classics/jizhu/018.md"}'),l={name:"classics/jizhu/018.md"};function t(h,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_14、【大有】-乾下離上" tabindex="-1">14、【大有】 乾下離上 <a class="header-anchor" href="#_14、【大有】-乾下離上" aria-label="Permalink to “14、【大有】 乾下離上”">​</a></h1><p>大有者，所有之大也。火在天上，萬物畢照，所照皆其所有，大有之象也。一柔居尊，眾陽並從，諸爻皆六五之所有，大有之義也。《序卦》“與人同者，物必歸焉，故受之以大有”，所以次同人。</p><p>《彖》曰：大有，柔得尊位，大中而上下應之，曰大有。其德剛健而文明，應乎天而時行，是以元亨。</p><p>以卦綜釋卦名，以卦德卦體釋卦辭。大有綜同人，柔得尊位而大中者，同人下卦之離往於大有之上卦，得五之尊位，居大有之中，而上下五陽皆從之也。上下從之，則五陽皆其所有矣。陽大陰小，所有者皆陽，故曰大有。內剛健則克勝其私，自誠而明也;外文明則灼見其理，自明而誠也。上下應之者，眾陽應乎六五也。應天時行者，六五應乎九二也。時者，當其可之謂。天即理也，天之道，不外時而已。應天時行，如天命有德，則應天而時章之;天討有罪，皆應天而時用之是也。乾為天，因應幹，故發此句。時行即應天之實，非時行之外別有應天也。剛健文明者德之體，應天時行者德之用。有是德之體用，則能亨其大有矣，是以元亨。</p><h3 id="《象》曰-火在天上-大有-君子以遏惡揚善-順天休命。" tabindex="-1">《象》曰：火在天上，大有，君子以遏惡揚善，順天休命。 <a class="header-anchor" href="#《象》曰-火在天上-大有-君子以遏惡揚善-順天休命。" aria-label="Permalink to “《象》曰：火在天上，大有，君子以遏惡揚善，順天休命。”">​</a></h3><p>火在天上無所不照，則善惡畢照矣。遏惡者，五刑五用是也。揚善者，五服五章是也。休，美也。天命之性，有善無惡，故遏惡揚善者，正所以順天之美命也。</p><p>初九，無交害，匪咎，艱則無咎。</p><p>害者，害我之大有也。離為戈兵，應爻戈兵在前，惡人傷害之象也，故睽卦離在前，亦曰見惡人。夬乃同體之卦，二爻變離，亦曰莫夜有戎。初居下位，以凡民而大有，家肥屋潤，人豈無害之理?離火克幹金，其受害也必矣。無交害者，去離尚遠，未交離之境也。九三交離境，故曰小人害也。九三害字人此害字來。匪咎者，人來害我，非我之咎也。艱者，艱難以保其大有，如夬之惕號也。</p><p>初九居卑，當大有之初，應爻離火，必有害我之幹金者。然陽剛得正，去離尚遠，故有無交害匪咎之象。然或以匪咎而以易心處之，則必受其害矣。惟艱，則可保其大有而無咎也，故又教佔者以此。</p><h3 id="《象》曰-大有初九-無交害也。" tabindex="-1">《象》曰：大有初九，無交害也。 <a class="header-anchor" href="#《象》曰-大有初九-無交害也。" aria-label="Permalink to “《象》曰：大有初九，無交害也。”">​</a></h3><p>時大有而當其初，所以去離遠而無交害。</p><p>九二，大車以載，有攸往，無咎。</p><p>幹錯坤，為大輿，大車之象也。陽上行之物，車行之象也。以者用也，用之以載也。變離錯坎，坎中滿，以載之象也。大車以載之重，九二能任重之象也。二變中爻成巽，巽為股，巽錯震為足，股足震動，有攸往之象也。</p><p>九二當大有之時，中德蓄積，充實富有，乃應六五之交孚，故有大車以載之象。有所往而如是則可以負荷其任，佐六五虛中之君，共濟大有之盛，而無咎矣，故其佔如此。</p><h3 id="《象》曰-大車以載-積中不敗也。" tabindex="-1">《象》曰：大車以載，積中不敗也。 <a class="header-anchor" href="#《象》曰-大車以載-積中不敗也。" aria-label="Permalink to “《象》曰：大車以載，積中不敗也。”">​</a></h3><p>幹三連陽多之卦皆曰積，積聚之意。小畜夬皆五陽一陰同體之卦，故小畜曰積德載，此曰以載，而又曰積中者，言積陽德而居中也，則小畜之積德載愈明矣。夬九二《小象》曰得中道也，小畜九二《小象》曰，牽覆在中，皆此中之意。敗字在車上來，幹金遇離火，必受克而敗壞，故初曰無交害，三曰小人害，則敗字雖從車上來，亦害字之意。曰中德所以不敗壞也，曰積中不敗，則離火不燒金，六五厥孚交如，與九二共濟大有之太平矣。</p><p>九三，公用亨於天子，小人弗克。</p><p>三居下卦之上，故曰公。五雖陰爻，然居大位，三非正應，故稱天子。亨者，陽剛居正，不以大有自私，亨之象也。卦本元亨，故曰亨。用亨於天子者，欲出而有為，以亨六五大有之治也。九二中德，止曰大車以載，不言亨於天子，而九三反欲亨於天子，何也?蓋九三才剛志剛，所以用亨天子也。同人大有相綜之卦，同人三四皆欲同乎二，所以大有二三皆欲共濟五之大有也。小人指四也，弗克者，不能也。三欲亨於天子，四持戈兵，阻而害之，因此小人所以弗亨於天子也。蓋大有之四，即同人之三，四持戈兵，即三之伏戎也。二三變為睽，輿曳牛掣，即小人之阻不能用亨也。舊注作享者非，用亨天子，猶言出而使天子亨，大有之亨也。</p><p>九三當大有之時，亦欲濟亨通之會，亨於天子，而共保大有之治者也。但當離幹交會之間，金受火制，小人在前，不能遽達，故有弗克，亨於天子之象。佔者得此，不當如九二之有攸往也，可知矣。</p><h3 id="《象》曰-公用亨於天子-小人害也。" tabindex="-1">《象》曰：公用亨於天子，小人害也。 <a class="header-anchor" href="#《象》曰-公用亨於天子-小人害也。" aria-label="Permalink to “《象》曰：公用亨於天子，小人害也。”">​</a></h3><p>因小人害，所以弗克亨於天子，周公之無交害者，初之遠於四也。孔子之小人害者，三之近於四也。</p><p>九四，匪其彭，無咎。</p><p>彭鼓聲，又盛也，言聲勢之盛也。四變中爻為震，震為鼓，彭之象也，變艮，止*其盛之象也。</p><ul><li>原文作土，應為止之誤。</li></ul><p>九四居大有之時，已過中矣，乃大有之極盛者也，近君豈可極盛。然以剛居柔，故有不極其聲勢之盛之象，無咎之道也。故其佔如此。</p><h3 id="《象》曰-匪其彭無咎-明辯晳也。" tabindex="-1">《象》曰：匪其彭無咎，明辯晳也。 <a class="header-anchor" href="#《象》曰-匪其彭無咎-明辯晳也。" aria-label="Permalink to “《象》曰：匪其彭無咎，明辯晳也。”">​</a></h3><p>晳，明貌，晳然其明辯也，離明之象也。明辯者，辯其所居之地乃別嫌多懼之地，辯其所遇之時乃盛極將衰之時也。</p><p>六五，厥孚交如，威如吉。</p><p>威如者，恭己無為，平易而不防閒備，具特有人君之威而已。因六五其體文明，其德中順，又有陽剛群賢輔之，即舜之無為而治矣，所以有此象。</p><p>六五當大有之世，文明中順，以居尊位，虛己誠信，以任九二之賢。不惟九二有孚於五，而上下之陽，亦皆以誠信歸之。是其孚信之交，無一毫之偽者也。是以為六五者，賴群賢以輔治，惟威如而已。此則不言而信，不怒而民威於鈇鉞，蓋享大有太平之福者也，何吉如之。故其象佔如此。</p><h3 id="《象》曰-厥孚交如-信以發志也。威如之吉-易而無備也。" tabindex="-1">《象》曰：厥孚交如，信以發志也。威如之吉，易而無備也。 <a class="header-anchor" href="#《象》曰-厥孚交如-信以發志也。威如之吉-易而無備也。" aria-label="Permalink to “《象》曰：厥孚交如，信以發志也。威如之吉，易而無備也。”">​</a></h3><p>誠能動物，一人之信，足以發上下相信之志也。易而無備者，凡人君任賢圖治，若機心深刻而過於防閒預備，則易生嫌隙，決不能與所任用之賢厥孚交如矣。惟平易而不防備，則任賢勿貳，去邪勿疑，方可享無為之治矣。威如即恭己，易而無備即無為。若依舊注作戒辭，則小象止當曰威如則吉，不應曰威如之吉也。</p><p>上九，自天祐之，吉無不利。</p><p>上九以剛明之德，當大有之盛。既有崇高之富貴，而下有六五柔順之君，剛明之群賢輔之，上九蓋無所作為，惟享自天祐助之福，吉而無不利者也。佔者有是德，居是位，斯應是佔矣。</p><h3 id="《象》曰-大有上吉-自天祐也。" tabindex="-1">《象》曰：大有上吉，自天祐也。 <a class="header-anchor" href="#《象》曰-大有上吉-自天祐也。" aria-label="Permalink to “《象》曰：大有上吉，自天祐也。”">​</a></h3><p>言皆天之祐助，人不可得而為也。上居天位，故曰天。此爻止有天祐之意，若繫辭，又別發未盡之意也。如公用射隼，止有解悖之意。若成器而動，又未盡之意也。言各不同，皆發未盡之意。舊注泥於繫辭者非。</p>',36)])])}const m=e(l,[["render",t]]);export{_ as __pageData,m as default};
